export class AuthService{static API_URL="/api/auth";static async handleResponse(t,e){const a=t.headers.get("content-type");let o;if(!a||!a.includes("application/json")){const e=await t.text();throw new Error(e||"Too many requests, please try again later.")}if(o=await t.json(),!t.ok)throw new Error(o.message||e);return o}static async register(t,e,a){const o=await fetch(`${this.API_URL}/register`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:t,email:e,password:a})});return this.handleResponse(o,"Registration failed")}static async login(t,e){const a=await fetch(`${this.API_URL}/login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:t,password:e})}),o=await this.handleResponse(a,"Login failed");return o.token&&localStorage.setItem("authToken",o.token),o}static logout(){localStorage.removeItem("authToken")}static getToken(){return localStorage.getItem("authToken")}static isAuthenticated(){return!!this.getToken()}static async getCurrentUser(){const t=this.getToken();if(!t)throw new Error("No authentication token found");const e=await fetch(`${this.API_URL}/me`,{method:"GET",headers:{Authorization:`Bearer ${t}`,"Content-Type":"application/json"}});return(await this.handleResponse(e,"Failed to get user data")).user}static async uploadAvatar(t){const e=this.getToken();if(!e)throw new Error("No authentication token found");const a=new FormData;a.append("avatar",t);const o=await fetch(`${this.API_URL}/upload-avatar`,{method:"POST",headers:{Authorization:`Bearer ${e}`},body:a});return this.handleResponse(o,"Failed to upload avatar")}static async updateUsername(t){const e=this.getToken();if(!e)throw new Error("No authentication token found");const a=await fetch(`${this.API_URL}/update-username`,{method:"POST",headers:{Authorization:`Bearer ${e}`,"Content-Type":"application/json"},body:JSON.stringify({newUsername:t})});return this.handleResponse(a,"Failed to update username")}static async updateEmail(t){const e=this.getToken();if(!e)throw new Error("No authentication token found");const a=await fetch(`${this.API_URL}/update-email`,{method:"POST",headers:{Authorization:`Bearer ${e}`,"Content-Type":"application/json"},body:JSON.stringify({newEmail:t})});return this.handleResponse(a,"Failed to update email")}static async requestPasswordReset(t){const e=await fetch(`${this.API_URL}/forgot-password`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:t})});return this.handleResponse(e,"Failed to request reset")}static async resetPassword(t,e,a){const o=await fetch(`${this.API_URL}/reset-password`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:t,code:e,newPassword:a})});return this.handleResponse(o,"Failed to reset password")}static async changePassword(t,e){const a=this.getToken();if(!a)throw new Error("No authentication token found");const o=await fetch(`${this.API_URL}/change-password`,{method:"POST",headers:{Authorization:`Bearer ${a}`,"Content-Type":"application/json"},body:JSON.stringify({currentPassword:t,newPassword:e})});return this.handleResponse(o,"Failed to change password")}}